from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='El ADN guarda las instrucciones genéticas de la célula y se copia antes de cada división. Este capítulo describe su estructura química, cómo se organiza en cromosomas, el mecanismo semiconservador de la replicación y un cálculo que muestra por qué un genoma grande no puede copiarse desde un único punto de origen.',
        quotes=[Q('es_adn','contiene las instrucciones genéticas fundamentales para el desarrollo, funcionamiento y reproducción de todos los seres vivos'), Q('en_dna','The polymer carries genetic instructions for the development, functioning, growth and reproduction of all known organisms and many viruses.')]))
    P.append(dict(text='El ADN es un polímero de nucleótidos. Cada nucleótido está formado por un azúcar, la desoxirribosa, una base nitrogenada, que puede ser adenina, timina, citosina o guanina, y un grupo fosfato. Los nucleótidos se unen en una cadena por enlaces covalentes entre el azúcar de uno y el fosfato del siguiente, lo que da un esqueleto alternante de azúcar y fosfato. Lo que distingue a un polinucleótido de otro es la base nitrogenada, y por eso la secuencia del ADN se especifica nombrando solo sus bases.',
        quotes=[Q('es_adn','Desde el punto de vista químico, el ADN es un polímero de nucleótidos, es decir, un polinucleótido.'), Q('en_dna','The nucleotides are joined to one another in a chain by covalent bonds (known as the phosphodiester linkage) between the sugar of one nucleotide and the phosphate of the next, resulting in an alternating sugar-phosphate backbone.'), Q('es_adn','Lo que distingue a un polinucleótido de otro es, entonces, la base nitrogenada')]))
    P.append(dict(text='Dos cadenas de ADN se enroscan para formar una doble hélice. Las bases de las dos cadenas se unen según reglas de apareamiento, adenina con timina y citosina con guanina, mediante puentes de hidrógeno. Como esos puentes no son enlaces covalentes, pueden romperse y recomponerse con relativa facilidad, de modo que las dos cadenas se pueden separar como una cremallera. El modelo de la doble hélice lo propusieron James Watson y Francis Crick en 1953; el surco mayor mide 22 ångström (2,2 nm) de ancho y el menor 12 Å (1,2 nm).',
        quotes=[Q('en_dna','The nitrogenous bases of the two separate polynucleotide strands are bound together, according to base pairing rules (A with T and C with G), with hydrogen bonds to make double-stranded DNA.'), Q('en_dna','The two strands of DNA in a double helix can thus be pulled apart like a zipper'), Q('es_adn','El modelo de estructura en doble hélice fue propuesto en 1953 por James Watson'), Q('en_dna','The major groove is 22 ångströms (2.2 nm) wide, while the minor groove is 12 Å (1.2 nm) in width.')]))
    P.append(dict(text='El tamaño de una molécula de ADN se indica por su número de pares de bases, con la kilobase (kb) igual a 1000 pares y la megabase (Mb) igual a un millón. El genoma humano haploide tiene alrededor de 3000 millones de pares de bases, y el mayor cromosoma humano, el 1, tiene aproximadamente 220 millones según una fuente, aunque el ensamblado de referencia actual da unos 249 millones. Otra fuente, el glosario del Instituto Nacional de Investigación del Genoma Humano de Estados Unidos, indica casi tres mil millones de pares de bases por copiar, lo que concuerda.',
        quotes=[Q('es_adn','Se estima que el genoma humano haploide tiene alrededor de 3000 millones de pares de bases.'), Q('es_adn','la kilobase (kb), que equivale a 1000 pares de bases, y la megabase (Mb), que equivale a un millón de pares de bases'), Q('es_adn','el cromosoma humano más largo, el cromosoma número 1, tiene aproximadamente 220 millones de pares de bases'), Q('nhgri_replication','there are almost three billion base pairs of DNA to be copied')]))
    P.append(dict(text='El ADN se organiza en cromosomas, estructuras filamentosas formadas por proteína y una sola molécula de ADN que llevan la información genómica de una célula a otra. En el ser humano hay 22 pares de cromosomas numerados, los autosomas, y un par de cromosomas sexuales, en total 46, y cada par tiene un cromosoma de cada progenitor. La cifra de 46 se determinó en 1956 por Joe Hin Tjio; antes se creía que eran 48. Los procariotas tienen típicamente un solo cromosoma circular.',
        quotes=[Q('nhgri_chromosome','Humans have 22 pairs of numbered chromosomes (autosomes) and one pair of sex chromosomes (XX or XY), for a total of 46.'), Q('en_chromosome','it was not until 1956 that the true number (46) was determined by Indonesian-born cytogeneticist Joe Hin Tjio'), Q('es_cromosoma','Puede observarse que en este cariotipo hay 46 cromosomas (o sea, 2n=46) que es el número cromosómico de la especie humana.'), Q('en_chromosome','The prokaryotes – bacteria and archaea – typically have a single circular chromosome.')]))
    P.append(dict(text='La replicación es el proceso por el que una célula hace copias exactas de su ADN, esencial para la herencia, la división celular y la reparación de tejidos. Es semiconservadora: las dos cadenas se separan y cada una sirve de molde para sintetizar una cadena complementaria nueva, de modo que cada molécula hija contiene una cadena original y una nueva. El experimento de Meselson y Stahl de 1958, con Escherichia coli cultivada con nitrógeno-15, un isótopo más pesado, permitió demostrar que el mecanismo real es el semiconservador.',
        quotes=[Q('en_replication','During replication, the two strands are separated, and each strand of the original DNA molecule then serves as a template for the production of a complementary counterpart strand, a process referred to as semiconservative replication.'), Q('es_replicacion','Esta duplicación del material genético se produce de acuerdo con un mecanismo semiconservador'), Q('es_replicacion','El experimento de Meselson y Stahl en 1958 permitió demostrar que el mecanismo real se ajusta a la hipótesis de replicación semiconservadora.')]))
    P.append(dict(text='La replicación empieza en puntos concretos llamados orígenes de replicación, repartidos por el genoma. Las helicasas desenrollan el ADN en el origen y se forman horquillas de replicación que crecen en las dos direcciones. La ADN polimerasa sintetiza las cadenas nuevas incorporando nucleótidos complementarios a los de la cadena molde. La cadena que se sintetiza en el sentido de avance de la horquilla, o conductora, se sintetiza de forma continua; la otra, la rezagada, se sintetiza de forma discontinua en fragmentos de Okazaki, de 1000 a 2000 nucleótidos en bacterias y de 100 a 400 en eucariontes.',
        quotes=[Q('en_replication','DNA replication usually begins at specific locations known as origins of replication which are scattered across the genome.'), Q('en_replication','Unwinding of DNA at the origin is accommodated by enzymes known as helicases and results in replication forks growing bi-directionally from the origin.'), Q('es_replicacion','Su longitud suele variar entre 1000 y 2000 nucleótidos en las bacterias y entre 100 y 400 nucleótidos en eucariontes.')]))
    P.append(dict(text='La replicación es muy rápida y muy fiel. En el fago T4, que infecta a E. coli, la velocidad de elongación del ADN durante el aumento exponencial a 37 °C fue de 749 nucleótidos por segundo, y la tasa de mutación por par de bases y replicación fue de 1,7 por 10^8. Los mecanismos celulares de lectura de prueba y de comprobación de errores aseguran una fidelidad casi perfecta. Es la velocidad medida en un fago; las fuentes no dan la equivalente para células humanas, y por eso este libro no la extrapola sin avisar.',
        quotes=[Q('en_replication','During the period of exponential DNA increase at 37 °C, the rate was 749 nucleotides per second.'), Q('en_replication','The mutation rate per base pair per replication during phage T4 DNA synthesis is 1.7 per 108.'), Q('en_replication','Cellular proofreading and error-checking mechanisms ensure near-perfect fidelity for DNA replication.'), Q('nhgri_replication','Replicating all of the DNA in a single human cell takes several hours of just pure copying time.')]))
    P.append(dict(text='Con esas cifras se puede probar por qué el genoma humano necesita muchos orígenes. A 749 nucleótidos por segundo, una sola horquilla tardaría 3000 millones dividido entre 749, es decir, unos 4,0 millones de segundos, más de 46 días. Dos horquillas que avancen en direcciones opuestas desde un solo origen reducirían ese tiempo a la mitad, unos 23 días, que sigue sin acercarse a las pocas horas que da el glosario del instituto. Hacen falta muchas horquillas simultáneas, y eso es coherente con que los orígenes de replicación estén repartidos por todo el genoma. El cálculo es una estimación de orden de magnitud con la velocidad de un fago, no de una célula humana.',
        quotes=[Q('en_replication','During the period of exponential DNA increase at 37 °C, the rate was 749 nucleotides per second.'), Q('es_adn','Se estima que el genoma humano haploide tiene alrededor de 3000 millones de pares de bases.'), Q('nhgri_replication','Replicating all of the DNA in a single human cell takes several hours of just pure copying time.')]))
    P.append(dict(role='definition', text='Replicación semiconservadora: mecanismo por el cual cada molécula de ADN hija contiene una cadena original, que sirvió de molde, y una cadena nueva complementaria.',
        quotes=[Q('es_replicacion','de forma que cada nueva doble hélice contiene una de las cadenas del ADN original'), Q('en_replication','As a result, each replicated DNA molecule is composed of one original DNA strand as well as one newly synthesized strand.')]))
    P.append(dict(role='consejo', text='Cuando una velocidad proceda de un organismo o de un virus concreto, anótelo junto con la cifra. Los 749 nucleótidos por segundo son del fago T4 en E. coli; usarlos para el ser humano da solo una estimación de orden de magnitud, no una predicción.',
        quotes=[Q('en_replication','749 nucleotides per second'), Q('nhgri_replication','takes several hours of just pure copying time')]))
    P.append(dict(role='self_check', text='¿Qué significa que la replicación sea semiconservadora y qué experimento lo demostró? ¿Por qué el genoma humano no puede copiarse desde un único origen? ¿Qué diferencia hay entre la hebra conductora y la rezagada?',
        quotes=[Q('es_replicacion','hebra adelantada o conductora y se sintetiza de forma continua por la ADN polimerasa'), Q('en_replication','the lagging strand is extended discontinuously from each primer forming Okazaki fragments')]))
    return P

def problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='El genoma humano haploide tiene unos 3000 millones de pares de bases y, en el fago T4, una horquilla de replicación avanza a 749 nucleótidos por segundo. Calcule cuántos días tardaría una sola horquilla en copiarlo y cuántas horquillas simultáneas harían falta para copiarlo en 8 horas.',
        expected='46.4', quotes=[Q('es_adn','Se estima que el genoma humano haploide tiene alrededor de 3000 millones de pares de bases.'), Q('en_replication','During the period of exponential DNA increase at 37 °C, the rate was 749 nucleotides per second.')],
        method='Tiempo de copia con una velocidad constante y número de horquillas',
        solution=dict(given=[dict(symbol='N',value=3000000000,unit='dimensionless',meaning='pares de bases del genoma haploide'),dict(symbol='v',value=749,unit='dimensionless',meaning='nucleótidos por segundo por horquilla'),dict(symbol='t_c',value=28800,unit='s',meaning='tiempo disponible, 8 h')],
          unknown='Los días que tarda una horquilla y las horquillas necesarias para copiar en 8 h.',
          model=[dict(name='Tiempo con una horquilla',latex='t_1 = N / v',symbolic='N/v'),dict(name='Horquillas necesarias',latex='n = t_1 / t_c',symbolic='N/v/t_c')],
          assumptions=['Cada horquilla copia un nucleótido por posición a velocidad constante.','Se usa la velocidad del fago T4, que es la única velocidad de horquilla que dan las fuentes.','Se ignoran las pausas, y se cuenta cada par de bases una sola vez.'],
          development=['El tiempo en segundos se divide entre 86 400 para tener días; las horquillas necesarias salen de dividir ese tiempo entre las 8 h disponibles.'],
          steps=[dict(text='Segundos con una horquilla',equation='t_1 = 3\\,000\\,000\\,000 / 749',expression='3000000000/749',expected=4005340.45,unit='s'),
                 dict(text='Días con una horquilla',equation='t_1 / 86\\,400',expression='3000000000/749/86400',expected=46.358,unit='d'),
                 dict(text='Horquillas necesarias en 8 h',equation='n = t_1 / 28\\,800',expression='3000000000/749/28800',expected=139.07,unit='dimensionless')],
          result='Una sola horquilla tardaría unos 46,4 días; para copiarlo en 8 horas harían falta unas 139 horquillas simultáneas.',
          interpretation='Un solo origen es inviable para un genoma de este tamaño, lo que concuerda con los muchos orígenes de replicación repartidos por el genoma.',
          limitations=['Si la velocidad en células humanas fuera otra, el resultado cambiaría en proporción inversa; las fuentes no la dan.','El genoma diploide tiene el doble de ADN que el haploide.'],
          mistakes=['Olvidar que las horquillas avanzan en dos direcciones desde cada origen, lo que reduce a la mitad el número de orígenes necesarios.']))]


